export const KEY='jinmotion.v1';
export const APP_VERSION='0.2.4';
export const MEASUREMENT_METHOD='mediapipe-1.2.2-full-image-plane-knee-interior-angle-v2';
const LEGACY_METHOD='mediapipe-1.2.2-image-plane-knee-interior-angle-v1';
const methodFor=value=>value===MEASUREMENT_METHOD?MEASUREMENT_METHOD:LEGACY_METHOD;
export const MAX_SAMPLES=1800;
export function freshState(){return {version:1,lang:'yue',voiceEnabled:true,pre:0,feedback:'summary',custom:false,plan:[{id:0,reps:6},{id:2,reps:6},{id:3,reps:6}],logs:[],draft:null}}
export function validatePlan(plan){return Array.isArray(plan)&&plan.length>0&&plan.length<=8&&new Set(plan.map(x=>x.id)).size===plan.length&&plan.every(x=>Number.isInteger(x.id)&&x.id>=0&&x.id<8&&Number.isInteger(x.reps)&&x.reps>=1&&x.reps<=30)}
const finite=(v,min,max)=>Number.isFinite(v)&&v>=min&&v<=max;
const dateOK=v=>typeof v==='string'&&Number.isFinite(Date.parse(v));
function validCounts(counts,plan){return Array.isArray(counts)&&counts.length===plan.length&&counts.every((v,i)=>Number.isInteger(v)&&v>=0&&v<=plan[i].reps)}
export function sanitizeSamples(samples){if(samples===undefined)return [];if(!Array.isArray(samples)||samples.length>MAX_SAMPLES)throw Error('Invalid measurements');return samples.map(s=>{if(!s||!dateOK(s.at)||!finite(s.elapsed,0,86400)||!Number.isInteger(s.moveId)||s.moveId<0||s.moveId>7||(![null,undefined].includes(s.left)&&!finite(s.left,0,180))||(![null,undefined].includes(s.right)&&!finite(s.right,0,180))||!finite(s.width,1,16384)||!finite(s.height,1,16384)||!['unmarked','front','leftSide','rightSide'].includes(s.view))throw Error('Invalid measurements');return {at:s.at,elapsed:s.elapsed,moveId:s.moveId,left:s.left??null,right:s.right??null,width:s.width,height:s.height,view:s.view,method:methodFor(s.method)}})}
export function sanitizeLog(l){if(!l||typeof l.id!=='string'||!l.id.length||l.id.length>128||!dateOK(l.startedAt)||!dateOK(l.endedAt)||Date.parse(l.endedAt)<Date.parse(l.startedAt)||!finite(l.seconds,0,86400)||!validatePlan(l.plan)||!validCounts(l.counts,l.plan)||![l.pre,l.post,l.effort].every(v=>Number.isInteger(v)&&finite(v,0,10))||!['summary','realtime'].includes(l.feedback)||!['completed','stopped'].includes(l.status)||typeof l.note!=='string'||l.note.length>1000)throw Error('Invalid session');const percent=completion(l.counts,l.plan);if(l.completion!==percent||l.status!==(percent===100?'completed':'stopped'))throw Error('Invalid completion');return {id:l.id,startedAt:l.startedAt,endedAt:l.endedAt,seconds:l.seconds,plan:l.plan.map(x=>({id:x.id,reps:x.reps})),counts:[...l.counts],pre:l.pre,post:l.post,effort:l.effort,note:l.note,feedback:l.feedback,aiFeedbackDelivered:false,completion:percent,status:l.status,appVersion:typeof l.appVersion==='string'?l.appVersion.slice(0,20):'0.1.0',measurementMethod:methodFor(l.measurementMethod),samples:sanitizeSamples(l.samples)}}
export function sanitizeDraft(d){try{if(!d||typeof d.id!=='string'||!d.id.length||d.id.length>128||!dateOK(d.startedAt)||!validatePlan(d.plan)||!validCounts(d.counts,d.plan)||!Number.isInteger(d.index)||d.index<0||d.index>=d.plan.length||!Number.isInteger(d.pre)||!finite(d.pre,0,10)||!finite(d.elapsed,0,86400)||!['summary','realtime'].includes(d.feedback))return null;return {id:d.id,startedAt:d.startedAt,plan:d.plan.map(x=>({id:x.id,reps:x.reps})),counts:[...d.counts],index:d.index,pre:d.pre,feedback:d.feedback,elapsed:d.elapsed,running:false,samples:sanitizeSamples(d.samples),post:Number.isInteger(d.post)&&finite(d.post,0,10)?d.post:d.pre,effort:Number.isInteger(d.effort)&&finite(d.effort,0,10)?d.effort:0,note:typeof d.note==='string'?d.note.slice(0,1000):''}}catch{return null}}
export function readState(storage){try{const raw=storage.getItem(KEY);if(!raw)return freshState();const x=JSON.parse(raw);if(x.version!==1||!validatePlan(x.plan)||!Array.isArray(x.logs))return freshState();const logs=[];for(const l of x.logs){try{const clean=sanitizeLog(l);if(!logs.some(old=>old.id===clean.id))logs.push(clean)}catch{}}const draft=sanitizeDraft(x.draft);return {...freshState(),voiceEnabled:x.voiceEnabled!==false,lang:['zh','yue','en'].includes(x.lang)?x.lang:'yue',pre:Number.isInteger(x.pre)&&finite(x.pre,0,10)?x.pre:0,custom:x.custom===true,feedback:x.feedback==='realtime'?'realtime':'summary',plan:x.plan.map(m=>({id:m.id,reps:m.reps})),logs,draft:draft&&!logs.some(l=>l.id===draft.id)?draft:null}}catch{return freshState()}}
export function mergeBackup(current,input){const b=typeof input==='string'?JSON.parse(input):input;if(!b||b.version!==1||!validatePlan(b.plan)||!Array.isArray(b.logs)||b.logs.length>10000)throw Error('Invalid backup');const incoming=b.logs.map(sanitizeLog);if(new Set(incoming.map(l=>l.id)).size!==incoming.length)throw Error('Duplicate session IDs');const ids=new Set(current.logs.map(l=>l.id)),added=incoming.filter(l=>!ids.has(l.id));return {state:{...current,plan:b.plan.map(m=>({id:m.id,reps:m.reps})),custom:b.custom===true,logs:[...current.logs,...added].sort((a,b)=>Date.parse(a.endedAt)-Date.parse(b.endedAt))},added:added.length,skipped:incoming.length-added.length}}
export function completion(counts,plan){const target=plan.reduce((n,x)=>n+x.reps,0);return target?Math.round(100*plan.reduce((n,x,i)=>n+Math.min(x.reps,Math.max(0,counts[i]||0)),0)/target):0}
export function csvCell(v){let s=String(v??'');if(/^[=+@\-\t\r]/.test(s))s="'"+s;return '"'+s.replaceAll('"','""')+'"'}
export function exportCsv(logs){const cols=['id','started_at','ended_at','active_seconds','pain_before','pain_after','exertion','completion_percent','status','feedback_preference','ai_feedback_delivered','note','plan_json','counts_json','app_version','measurement_samples'];const rows=logs.map(l=>[l.id,l.startedAt,l.endedAt,l.seconds,l.pre,l.post,l.effort,l.completion,l.status,l.feedback,false,l.note,JSON.stringify(l.plan),JSON.stringify(l.counts),l.appVersion||'0.1.0',l.samples?.length||0]);return '\uFEFF'+[cols,...rows].map(r=>r.map(csvCell).join(',')).join('\r\n')}
export function exportMeasurements(logs){const columns=['session_id','sample_time','active_seconds','movement_id_zero_based','camera_view','image_width','image_height','left_projected_knee_interior_angle_deg','right_projected_knee_interior_angle_deg','method','clinically_validated'];const data=logs.flatMap(l=>(l.samples||[]).map(s=>[l.id,s.at,s.elapsed,s.moveId,s.view,s.width,s.height,s.left,s.right,s.method||l.measurementMethod||LEGACY_METHOD,false]));return '\uFEFF'+[columns,...data].map(row=>row.map(csvCell).join(',')).join('\r\n')}
